 "content": "def transform(grid):
    """Expand each 3 marker into the observed five-row motif."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0]) if out else 0
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 3]

    for r, c in markers:
        # Top band, then the vertical side rails and central 5/3 column.
        for dc in range(-2, 3):
            rr, cc = r - 2, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 5
        for dr in (-1, 0, 1):
            rr = r + dr
            for dc in (-2, 2):
                cc = c + dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 2
        for dr, color in ((-1, 5), (0, 3)):
            rr, cc = r + dr, c
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
        # Bottom band: 8s in the five-cell span and 2s elsewhere on that row.
        rr = r + 2
        if 0 <= rr < h:
            out[rr] = [2] * w
            for cc in range(c - 2, c + 3):
                if 0 <= cc < w:
                    out[rr][cc] = 8
    return out
